+export const order = (events: readonly Event[]): Event[] => {
+  const sourceOrder = { checkout: 0, fulfilment: 1 };
+  return [...events].sort((a, b) => {
+    if (a.id !== b.id) return a.at - b.at;
+    const aSourcePriority = sourceOrder[a.source];
+    const bSourcePriority = sourceOrder[b.source];
+    if (aSourcePriority !== bSourcePriority) return aSourcePriority - bSourcePriority;
+    return a.at - b.at;
+  });
+};

